        source_title text,
        source_url text,
        scheduled_date date,
        status text,
        subject_slug text
    )
)
insert into public.weekly_sparks (
    id,
    spark_type,
    title,
    spark_text,
    why_it_matters,
    question,
    source_title,
    source_url,
    scheduled_date,
    status,
